#include <bits/stdc++.h>
using namespace std;

void apply(vector<int>& p, int x, int y) {
    int n = p.size();
    // [0..x-1] prefix, [x..n-y-1] middle, [n-y..n-1] suffix
    // result = suffix + middle + prefix
    vector<int> np;
    for (int i = n-y; i < n; i++) np.push_back(p[i]);
    for (int i = x; i < n-y; i++) np.push_back(p[i]);
    for (int i = 0; i < x; i++) np.push_back(p[i]);
    p = np;
}

int main(){
    int n;
    scanf("%d",&n);
    vector<int> p(n);
    for(int i=0;i<n;i++) scanf("%d",&p[i]);

    vector<pair<int,int>> ops;

    // Place elements 1,2,...,n into positions 0,1,...,n-1
    for(int placed = 0; placed < n; placed++){
        // Find where (placed+1) is
        int pos = -1;
        for(int i = placed; i < n; i++) if(p[i] == placed+1){ pos = i; break; }
        if(pos == placed) continue; // already in place

        // If only 2 elements left, one swap suffices (if possible)
        // Need to bring p[pos] to position 'placed'

        // Step 1: bring element to position n-1 if it's not there
        if(pos != n-1){
            // x = pos+1, y = n-1-pos => suffix starts at pos+1, has n-1-pos elements
            // After: suffix[pos+1..n-1] + middle[pos+1..pos] (empty if pos+1>pos) + prefix[0..pos]
            // Wait: middle = [x..n-y-1] = [pos+1..pos] which is empty when y=n-1-pos
            // x+y = pos+1+n-1-pos = n, need x+y < n. Not valid!
            // So use x=pos, y=n-1-pos. Then middle=[pos..pos]=one element (our target)
            // After: suffix[pos+1..n-1] + middle[pos] + prefix[0..pos-1]
            // Our element at pos goes to position (n-1-pos) in new array
            // Actually we need pos>0 for x>0 and n-1-pos>0 for y>0, and pos+n-1-pos=n-1<n. Good!
            if(pos > 0 && pos < n-1){
                int x = pos, y = n-1-pos;
                ops.push_back({x, y});
                apply(p, x, y);
                // Find element again
                for(int i = placed; i < n; i++) if(p[i] == placed+1){ pos = i; break; }
            }
        }

        if(pos == placed) continue;

        // Step 2: bring element from current pos to 'placed'
        // Use x=placed, y=n-pos. middle=[placed..n-1-y]=[placed..pos-1]
        // Need placed>0 (if placed==0, use x=1 trick or different approach)
        if(pos != placed){
            // x = n-pos, y = placed... wait let me think differently
            // We want element at pos to go to position placed
            // After op(x,y): suffix(y elems) + middle + prefix(x elems)
            // Element at pos: if pos >= n-y (in suffix), goes to pos-(n-y)
            // If pos < x (in prefix), goes to y + (n-x-y) + pos = n - x + pos
            // If x <= pos < n-y (in middle), goes to y + (pos - x)

            // Want result position = placed. Element at pos.
            // Try: put it in suffix. pos >= n-y => y >= n-pos. Want pos-(n-y)=placed => y=n-pos+placed. x>0,y>0,x+y<n => x<n-y=pos-placed. x>=1. So x=1,y=n-pos+placed. Check x+y=1+n-pos+placed<n => placed<pos-1. And y>0 always (pos<=n-1,placed>=0 => y>=1).
            if(placed < pos - 1 && 1 + n - pos + placed < n){
                int x = 1, y = n - pos + placed;
                ops.push_back({x, y});
                apply(p, x, y);
            } else if(placed < pos){
                // x=pos-placed, y=n-pos => element in middle? No, at boundary.
                // pos in suffix if pos>=n-y => pos >= pos => yes. Goes to pos-(n-y)=pos-pos=0... not placed unless placed=0
                // Try element in prefix: pos < x. Then goes to n-x+pos. Want n-x+pos=placed => x=n+pos-placed. x+y<n => n+pos-placed+y<n => y<placed-pos<0. No good.
                // Direct: x=pos-placed, y=n-pos. Suffix=[pos..n-1], middle=[pos-placed..pos-1], prefix=[0..pos-placed-1]. Element at pos is first of suffix, goes to position 0. Not placed (unless placed=0).
                if(placed == 0 && pos > 0 && pos < n){
                    int y_val = n - pos;
                    int x_val = 1; // just need something
                    // Actually for placed=0: want element to position 0. Put in suffix: pos>=n-y => y>=n-pos. Goes to pos-(n-y)=0 => y=n-pos. x>0, x+y<n => x < pos. x=1.
                    if(pos > 1){
                        ops.push_back({1, n-pos});
                        apply(p, 1, n-pos);
                    } else { // pos==1, placed==0
                        ops.push_back({1, n-2});
                        apply(p, 1, n-2);
                        for(int i=0;i<n;i++) if(p[i]==placed+1){pos=i;break;}
                        if(pos!=0){
                            ops.push_back({1, n-pos});
                            apply(p, 1, n-pos);
                        }
                    }
                } else {
                    // pos == placed+1 case
                    int x_val = placed+1, y_val = n-pos;
                    if(x_val>0 && y_val>0 && x_val+y_val<n){
                        ops.push_back({x_val, y_val});
                        apply(p, x_val, y_val);
                    }
                }
            }
        }
    }

    printf("%d\n",(int)ops.size());
    for(auto&[x,y]:ops) printf("%d %d\n",x,y);
}
